package local.spatialclient;
import java.util.*;import java.nio.file.*;import java.util.concurrent.atomic.AtomicReference;
import net.minecraft.client.*;import net.minecraft.resources.Identifier;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.effect.MobEffectInstance;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.world.phys.Vec3;import net.minecraft.world.level.GameType;
import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.client.event.ClientTickEvent;
import net.spell_engine.internals.*;import net.spell_engine.internals.target.SpellTarget;import net.paladins.entity.BarrierEntity;
@Mod(value="spatial_client_probe",dist=Dist.CLIENT) public class SpatialClientProbe {
 int ticks,phase,at;boolean pending;UUID target;final List<String> lines=new ArrayList<>();final AtomicReference<Throwable> error=new AtomicReference<>();
 public SpatialClientProbe(){NeoForge.EVENT_BUS.addListener(this::tick);}
 void check(boolean ok,String label){lines.add((ok?"PASS ":"FAIL ")+label);if(!ok)throw new AssertionError(label);}
 void server(java.util.function.Consumer<net.minecraft.server.level.ServerPlayer> job){var mc=Minecraft.getInstance();pending=true;mc.getSingleplayerServer().execute(()->{try{job.accept(mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID()));}catch(Throwable e){error.set(e);}finally{pending=false;}});}
 void step(){phase++;at=ticks;}
 void finish(){if(phase==99)return;phase=99;var mc=Minecraft.getInstance();try{Files.write(mc.gameDirectory.toPath().resolve("spatial-client-checks.txt"),lines);Files.writeString(mc.gameDirectory.toPath().resolve("spatial-client-result.txt"),lines.stream().anyMatch(s->s.startsWith("FAIL"))?"FAIL":"PASS");}catch(Exception ignored){}mc.stop();}
 void tick(ClientTickEvent.Post event){var mc=Minecraft.getInstance();ticks++;if(phase==99)return;try{
  if(error.get()!=null)throw new RuntimeException(error.get());if(pending||mc.player==null||mc.level==null||mc.getSingleplayerServer()==null)return;if(ticks-at>1800)throw new AssertionError("Timeout phase"+phase);
  if(phase==0){mc.options.pauseOnLostFocus=false;server(p->{p.setGameMode(GameType.SURVIVAL);p.teleportTo(0,101,0);p.setNoGravity(true);for(var old:p.level().getEntitiesOfClass(LivingEntity.class,p.getBoundingBox().inflate(100)))if(old!=p)old.discard();p.removeAllEffects();p.getAttribute(Attributes.SCALE).setBaseValue(2.5);var e=EntityTypes.CREEPER.create(p.level(),EntitySpawnReason.COMMAND);e.setPos(0,101,8);e.setNoAi(true);e.setNoGravity(true);e.getAttribute(Attributes.SCALE).setBaseValue(2);e.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);e.setHealth(1000);target=e.getUUID();p.level().addFreshEntity(e);});step();return;}
  if(ticks-at<40)return;
  if(phase==1){double expected=net.bettercombat.logic.PlayerAttackHelper.getRangeForItem(mc.player,mc.player.getMainHandItem())*net.bettercombat.BetterCombatMod.config.getAttackRangeMultiplierForScale(mc.player.getScale());check(Math.abs(mc.player.entityInteractionRange()-expected)<.01,"Client native reach matches BetterCombat at large size");server(p->{p.getAttribute(Attributes.SCALE).setBaseValue(1);p.setYRot(0);p.setXRot(0);});step();return;}
  if(phase==2){mc.setScreenAndShow(null);mc.player.setYRot(0);mc.player.setXRot(0);var s=PaladinRevamp.spell(mc.player,"wizards:arcane_explosion");var result=SpellTarget.findTargets(mc.player,s,SpellTarget.SearchResult.empty(),true);check(result.entities().stream().anyMatch(e->e.getUUID().equals(target)),"Client can initially highlight enemy");server(p->{var e=(LivingEntity)p.level().getEntity(target);e.addEffect(new MobEffectInstance(BuiltInRegistries.MOB_EFFECT.get(Identifier.parse("rogues:stealth")).orElseThrow(),400));});step();return;}
  if(phase==3){var remote=mc.level.getEntitiesOfClass(LivingEntity.class,mc.player.getBoundingBox().inflate(20),e->e.getUUID().equals(target)).getFirst();lines.add("CLIENT remote effects="+remote.getActiveEffects()+" invisible="+remote.isInvisible());var s=PaladinRevamp.spell(mc.player,"wizards:arcane_explosion");check(SpellTarget.findTargets(mc.player,s,SpellTarget.SearchResult.empty(),false).entities().stream().noneMatch(e->e.getUUID().equals(target)),"Client excludes vanished enemy before highlight");server(p->{var category=net.puffish.skillsmod.api.SkillsAPI.getCategory(Identifier.parse("skill_tree_rpgs:class_skills")).orElseThrow();category.unlock(p);category.setExtraPoints(p,1000);category.getSkill("tdimeso8ajcwiygp").orElseThrow().unlock(p);PaladinUltimates.startChannel(p,p.level().getGameTime());});step();return;}
  if(phase==4){var walls=mc.level.getEntitiesOfClass(BarrierEntity.class,mc.player.getBoundingBox().inflate(20),PurgatoryBoundary::is);check(walls.size()==1,"Boundary entity and spell synchronized to client");var b=walls.getFirst();check(PurgatoryBoundary.radius(b)==12,"Client boundary radius12");check(!b.canBeCollidedWith(mc.player),"Native square collision disabled for cylinder");mc.options.setCameraType(CameraType.THIRD_PERSON_BACK);mc.player.setYRot(0);mc.player.setXRot(12);Screenshot.grab(mc,false);step();return;}
  if(phase==5){check(net.paladins.client.entity.BoundaryRender.submissions>0&&net.paladins.client.entity.BoundaryRender.draws>0,"Orange boundary submitted to actual renderer");Screenshot.grab(mc,false);step();return;}
  if(phase==6){server(p->PaladinUltimates.end(p,PaladinUltimates.End.RELEASE));step();return;}
  if(phase==7){check(mc.level.getEntitiesOfClass(BarrierEntity.class,mc.player.getBoundingBox().inflate(20),PurgatoryBoundary::is).isEmpty(),"Early release removes client boundary");check(Math.abs(mc.player.entityInteractionRange()-3)<.01,"Client reach restores after size removal");finish();}
 }catch(Throwable e){e.printStackTrace();lines.add("FAIL "+e);finish();}}
}
